export const updateBuild = (
  getAuthorizationHeader: () => Promise<string>,
  userId: string,
  buildId: string,
  { name, description }: {| name?: string, description?: string |}
): Promise<Build> => {
  return getAuthorizationHeader()
    .then(authorizationHeader =>
      client.patch(
        `/build/${buildId}`,
        { name, description },
        {
          params: {
            userId,
          },
          headers: {
            Authorization: authorizationHeader,
          },
        }
      )
    )
    .then(response =>
      ensureObjectHasProperty({
        data: response.data,
        propertyName: 'id',
        endpointName: '/build/{id} of Build API',
      })
    );
};

export const deleteBuild = async (
  getAuthorizationHeader: () => Promise<string>,
  userId: string,
  buildId: string
): Promise<void> => {
  const authorizationHeader = await getAuthorizationHeader();

  await client.delete(`/build/${buildId}`, {
    params: {
      userId,
    },
    headers: {
      Authorization: authorizationHeader,
    },
  });
};

export const getUserSigningCredentials = async (
  getAuthorizationHeader: () => Promise<string>,
  userId: string
): Promise<Array<SigningCredential>> => {
  const authorizationHeader = await getAuthorizationHeader();

  const response = await client.get(`/signing-credential`, {
    params: {
      userId,
    },
    headers: {
      Authorization: authorizationHeader,
    },
  });

  return ensureIsArray({
    data: response.data,
    endpointName: '/signing-credential of Build API',
  });
};

